package mod.cdv.tnpc.tactical;
import java.util.*;
public final class NpcClinic20 {
 static final String[] KEYS={"head","body","leftArm","rightArm","leftLeg","rightLeg","leftFoot","rightFoot"};static final String[] PARTS={"HEAD","BODY","LEFT_ARM","RIGHT_ARM","LEFT_LEG","RIGHT_LEG","LEFT_FOOT","RIGHT_FOOT"};static Object json(){return SocialR.make("com.google.gson.JsonObject");}static void property(Object o,String k,Object v){Social.c(o,"addProperty",k,v);}
 static boolean injured(Object n,int part){NpcMedicine.init(n);return part>=0&&part<8&&Social.num(Social.c(Social.tag(n),"getDouble","np15_hp_"+KEYS[part]))<Social.num(Social.c(Social.tag(n),"getDouble","np15_max_"+KEYS[part]))-.001;}
 static void open(Object n,Object p){Conversation.SESSIONS.put(p,new Conversation.Session(n,Social.time(n)+1200));send(n,p);}
 static void send(Object n,Object p){Object data=json(),rows=SocialR.make("com.google.gson.JsonArray");String stage=Downed20.down(n)?"down":"examined";int progress=0;Downed20.Rescue rescue=Downed20.RESCUES.get(n);NpcMedicine.PlayerTreatment treatment=NpcMedicine.TREATMENTS.get(n);if(rescue!=null){stage="work";progress=(int)((Social.time(n)-rescue.start())*100/rescue.duration());}else if(treatment!=null){stage="work";progress=(int)((Social.time(n)-treatment.start())*100/60);}property(data,"stage",stage);property(data,"patient",Identity20.name(n));property(data,"progress",Math.max(0,Math.min(100,progress)));for(int i=0;i<8;i++){Object row=json();property(row,"index",i);property(row,"part",PARTS[i]);property(row,"injured",injured(n,i));property(row,"modes",16);property(row,"details","");Social.c(rows,"add",row);}Social.c(data,"add","rows",rows);TalkNetwork.send(p,"M20\n"+data);}
 static void changed(Object n){for(var entry:new ArrayList<>(Conversation.SESSIONS.entrySet()))if(entry.getValue().npc==n)try{send(n,entry.getKey());}catch(RuntimeException disconnected){}}
 static void closed(Object n){for(var entry:new ArrayList<>(Conversation.SESSIONS.entrySet()))if(entry.getValue().npc==n){try{TalkNetwork.send(entry.getKey(),"M20\n{\"stage\":\"closed\"}");}catch(RuntimeException disconnected){}Conversation.SESSIONS.remove(entry.getKey());}Downed20.RESCUES.remove(n);NpcMedicine.TREATMENTS.remove(n);}
 static int action(Object n,Object p,String action)throws Exception{if(action.equals("revive"))return Downed20.begin(n,p)?1:0;if(!action.startsWith("treat_"))return -1;int part;try{part=Integer.parseInt(action.substring(6));}catch(NumberFormatException bad){return 0;}if(Downed20.down(n)||!injured(n,part))return 0;boolean started=NpcMedicine.playerTreat(n,p,part);if(!started)Social.say(p,"soc.treat.need");send(n,p);return started?1:0;}
}
